    road([[78, -2], [74, 20, 82, 34, 72, 52], [64, 66, 70, 78, 60, 100]], 0.7, 'rgba(148,213,255,.22)', 'rgba(148,213,255,.05)');
    road([[-2, 84], [24, 80, 44, 86, 62, 80], [70, 77, 76, 74, 82, 70]], 0.8, 'rgba(255,255,255,.13)');
    road([[40, -2], [38, 30, 44, 60, 40, 100]], 0.8, 'rgba(255,255,255,.13)');
