    dt[0].textContent = lead ? 'Worth' : 'Value'; dt[1].textContent = lead ? 'Cost' : 'Effort';
    dd[0].textContent = f.v; dd[1].textContent = lead ? COST[f.e] : f.ef; dd[2].innerHTML = f.after ? 'Item ' + f.after : 'Nothing';
    var dev = card.querySelector('[data-rm-view="dev"]'), ld = card.querySelector('[data-rm-view="lead"]');
