    el.style.setProperty('--tm-bg', sh.css);
    var h = '<img class="tm-img" src="' + SHOP[IMG[d.k] || d.k.toLowerCase().replace(/ /g, '-')] + '" alt="" decoding="async"><i class="tm-mg" aria-hidden="true"></i><span class="tm-name">' + d.k + '</span>';
